  var t=totals(),rows=allRows();
  var h='<div class="info">Строк: <b>'+t.rows+'</b>, показателей: <b>'+t.ind+'</b>. Счёт выставляется по каждому показателю, проверьте список перед отправкой.</div>';
  /* items editor */
